// Test fixture dependency #2 (issue #89). Deliberately minimal and deliberately UNGRANTED: the
// tests that use it give it nothing in the policy, so every read below must be denied and
// recorded no matter what any OTHER package happens to be doing at the time.
//
// It exists because #89's worst property was not that the spawning package could read env — it
// is that the env gate was suspended PROCESS-WIDE, so a package with no grants at all read
// ungated for as long as someone else was inside a spawn. Proving that requires a second
// principal; fixture-dep cannot play both parts.
exports.read = (key) => process.env[key];

// The descriptor path too — the `get` trap's sibling hole (see shims/env.ts).
exports.readDescriptor = (key) => Object.getOwnPropertyDescriptor(process.env, key);

// Whole-environment harvest, the shape a real exfiltration payload uses.
exports.readAll = () => ({ ...process.env });
